package com.kdu.csdtdas.backend.entity;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="exam_timetable_import_rows")
public class ExamTimetableImportRow{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;
@ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="task_id") private ExamCourseTask task;
@Column(length=5000) private String sourceLine;private LocalDate proposedDate;private LocalTime proposedStart,proposedEnd;@Column(length=150) private String proposedVenue;
@Column(nullable=false) private boolean confirmed=false;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="confirmed_by_id") private User confirmedBy;private LocalDateTime confirmedAt;
public ExamTimetableImportRow(){}public Long getId(){return id;}public ExamCourseTask getTask(){return task;}public void setTask(ExamCourseTask v){task=v;}public String getSourceLine(){return sourceLine;}public void setSourceLine(String v){sourceLine=v;}public LocalDate getProposedDate(){return proposedDate;}public void setProposedDate(LocalDate v){proposedDate=v;}public LocalTime getProposedStart(){return proposedStart;}public void setProposedStart(LocalTime v){proposedStart=v;}public LocalTime getProposedEnd(){return proposedEnd;}public void setProposedEnd(LocalTime v){proposedEnd=v;}public String getProposedVenue(){return proposedVenue;}public void setProposedVenue(String v){proposedVenue=v;}public boolean isConfirmed(){return confirmed;}public void setConfirmed(boolean v){confirmed=v;}public User getConfirmedBy(){return confirmedBy;}public void setConfirmedBy(User v){confirmedBy=v;}public LocalDateTime getConfirmedAt(){return confirmedAt;}public void setConfirmedAt(LocalDateTime v){confirmedAt=v;}}